client = OpenAI()
# Fire off an async response but also start streaming immediately
stream = client.responses.create( model= "o3" , input = "Write a very long novel about otters in space." , background= True , stream= True , )
cursor = None
for event in stream: print (event) cursor = event.sequence_number
